"use strict";(globalThis.webpackChunkgrc||=[]).push([[84878],{81317(e){e.exports=JSON.parse('{"citeKey":"logan2024megammap","slug":"logan-2024-megammap-cbda","title":"MegaMmap: Blurring the Boundary Between Memory and Storage for Data-Intensive Workloads","authors":["L. Logan","X.-H. Sun","A. Kougkas"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00114","abstract":"Large-scale data analytics, scientific simulation, and deep learning codes in HPC perform massive computations on data greatly exceeding the bounds of main memory. These out-of-core al- gorithms suffer from severe data movement penalties, programming complexity, and limited code reuse. To solve this, HPC sites have steadily increased DRAM capacity. However, this is not sustainable due to financial and environmental costs. A more elegant, low-cost, and portable solution is to expand memory to distributed multi- tiered storage. In this work, we propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management. MegaMmap provides workload-aware data organization, eviction, and prefetching policies to reduce DRAM consumption while ensur- ing speedy access to critical data. A variety of memory coherence optimizations are provided through an intuitive hinting system. Evaluations show that various workloads can be executed with a fraction of the DRAM while offering competitive performance.","hasAbstract":true,"lede":"We propose MegaMmap: a software distributed shared memory (DSM) that enlarges effective memory capacity through intelligent tiered DRAM and storage management.","links":{"pdf":"https://grc.iit.edu/papers/2024/logan-2024-megammap-cbda.pdf","code":"https://github.com/grc-iit/mega_mmap"},"tags":["Memory","Storage","Hierarchical Storage","HPC","Operating Systems","LABIOS"],"_projectIds":["labios","chronolog","dtio"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","labios","dtio","chronolog","hermes"],"memberAuthors":["logan-luke","sun-xian-he","kougkas-anthony"],"funding":[{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"DOE","award":"DE-SC0024593","projectId":"dtio"}]}')}}]);